const VARIANT_NAMES=["God Emperor Doom", "Loki (God of Stories)", "Maestro", "Superior Spider-Man", "Infamous Iron Man", "King in Black", "Rune King", "Spider-Man 2099", "Dark Phoenix", "All-Black", "Cosmic Ghost Rider", "Old Man Logan", "Flashpoint Batman", "Injustice Superman", "Batman Who Laughs", "White Lantern", "Black Lantern"];
function CharCard({hero,onSelect,onBan,drafted,banned,disabled,accent,mode="draft",knowledgeMode=false}) {
  const [hov,setHov]=useState(false);
  const tier=getTier(hero);
  const roles=getRoles(hero.stats);
  const blocked=disabled||drafted||banned;
  return (
    <div onClick={()=>!blocked&&mode!=="ban"&&onSelect&&onSelect(hero)}
      onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{borderRadius:10,overflow:"hidden",position:"relative",
        border:drafted?`2px solid ${accent}66`:banned?"2px solid #ef535066":hov&&!blocked?`2px solid ${accent}`:"2px solid #131326",
        background:drafted?"#0d1117":banned?"#1a0808":hov&&!blocked?"#13132a":"#0d0d1e",
        opacity:(disabled&&!drafted&&!banned)?0.35:1,
        cursor:blocked?"default":"pointer",transition:"all 0.15s",
        transform:hov&&!blocked?"translateY(-2px)":"none",
        boxShadow:hov&&!blocked?`0 6px 24px ${accent}22`:"none"}}>
      <div style={{position:"relative",width:"100%",paddingTop:"133%",background:"#0a0a18",overflow:"hidden"}}>
        {hero.img?(
          <img src={hero.img} alt={hero.name}
            style={{position:"absolute",top:0,left:0,width:"100%",height:"100%",
              objectFit:"cover",objectPosition:"top center",display:"block",
              filter:banned?"grayscale(1) opacity(0.25)":drafted?"opacity(0.5)":"none"}}/>
        ):(
          <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",
            fontWeight:800,fontSize:18,color:"#2a2a3e"}}>{initials(hero.name)}</div>
        )}
        {!knowledgeMode&&<div style={{position:"absolute",top:5,left:5,background:TIER_COLOR[tier],
          color:"#000",fontSize:9,fontWeight:900,padding:"2px 5px",borderRadius:4,zIndex:2}}>{tier}</div>}
        <div style={{position:"absolute",top:5,right:5,background:accent+"dd",
          color:"#fff",fontSize:8,fontWeight:700,padding:"2px 5px",borderRadius:4,zIndex:2}}>{hero.universe}</div>
        {drafted&&<div style={{position:"absolute",inset:0,background:"#00000099",zIndex:3,
          display:"flex",alignItems:"center",justifyContent:"center",
          fontWeight:800,fontSize:10,color:accent,letterSpacing:1}}>✓ DRAFTED</div>}
        {banned&&<div style={{position:"absolute",inset:0,background:"#00000099",zIndex:3,
          display:"flex",alignItems:"center",justifyContent:"center",
          fontWeight:800,fontSize:10,color:"#ef5350",letterSpacing:1}}>✕ BANNED</div>}
      </div>
      <div style={{padding:"8px 9px"}}>
        <div style={{fontWeight:700,fontSize:11,color:"#eee",marginBottom:1,
          whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{hero.name}</div>
           {VARIANT_NAMES.includes(hero.name)&&<div style={{background:"linear-gradient(90deg,#c9a84c,#f5d78e)",color:"#1a1a00",fontSize:8,fontWeight:900,letterSpacing:1.5,padding:"2px 5px",borderRadius:3,marginTop:2}}>✦ VARIANT</div>}
        {!knowledgeMode&&<div style={{fontSize:9,color:"#444",marginBottom:5}}>{roles.join(" · ")}</div>}
        {knowledgeMode?(
          <div style={{fontSize:9,color:"#333",marginTop:4,fontStyle:"italic"}}>Trust your knowledge</div>
        ):(
          STAT_KEYS.map(k=><StatBar key={k} label={k} value={hero.stats[k]}/>)
        )}
      </div>
      {mode==="ban"&&(
        <div style={{padding:"0 9px 9px"}}>
          <button onClick={e=>{e.stopPropagation();onBan&&onBan(hero);}}
            style={{width:"100%",padding:"5px",cursor:"pointer",borderRadius:6,fontSize:10,fontWeight:700,
              background:banned?"#33111122":"#ef535022",color:banned?"#555":"#ef5350",
              border:banned?"1px solid #2a2a2a":"1px solid #ef535055"}}>
            {banned?"UNBAN":"BAN"}
          </button>
        </div>
      )}
    </div>
  );
}

// Animated rating gauge
function RatingGauge({score,animate=false,size=88}) {
  const [displayed,setDisplayed]=useState(animate?0:score);
  useEffect(()=>{
    if(!animate){setDisplayed(score);return;}
    let cur=0;
    const step=score/60;
    const iv=setInterval(()=>{
      cur+=step;
      if(cur>=score){setDisplayed(score);clearInterval(iv);}
      else setDisplayed(Math.round(cur));
    },16);
    return ()=>clearInterval(iv);
  },[score,animate]);
  const info=getRatingInfo(displayed);
  const C=2*Math.PI*36;
  const offset=C-(displayed/100)*C;
  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
      <svg width={size} height={size} viewBox="0 0 88 88">
        <circle cx={44} cy={44} r={36} fill="none" stroke="#131326" strokeWidth={7}/>
        <circle cx={44} cy={44} r={36} fill="none" stroke={info.color} strokeWidth={7}
          strokeDasharray={C} strokeDashoffset={offset} strokeLinecap="round"
          transform="rotate(-90 44 44)" style={{transition:"stroke-dashoffset 0.05s linear"}}/>
        <text x={44} y={40} textAnchor="middle" fill={info.color} fontSize={20} fontWeight={800}>{displayed}</text>
        <text x={44} y={53} textAnchor="middle" fill="#333" fontSize={8}>/100</text>
      </svg>
      <div style={{fontWeight:800,fontSize:11,color:info.color,letterSpacing:1,transition:"color 0.1s"}}>{info.label}</div>
    </div>
  );
}

